  "sourceNotes": {
    "MRK": {
      "16": [
        {
          "text": "最も古い写本といくつかの他の古代の証人には9–20節がない。",
          "beforeVerse": 8,
          "afterVerse": 9
        }
      ]
    },
    "JHN": {
      "7": [
        {
          "text": "一部の初期の写本にはヨハネ 7:53がこの場所にないが、含まれている",
          "beforeVerse": 52,
          "afterVerse": 53
        }
      ],
      "8": [
        {
          "text": "初期のいくつかの写本には、ヨハネ8:1 - 8:11がこの場所に含まれていませんが、含まれているものもあります",
          "beforeVerse": 0,
          "afterVerse": 1
        }
      ]
    }
  },
